async function main(ctx) {
  const http = ctx.lastOutputOf('http_list');
  const params = ctx.lastOutputOf('prepare');
  const { q, limit, offset } = params;

  const body = http && typeof http === 'object' ? http.body : http;
  const data = body && typeof body === 'object' && Array.isArray(body.data)
    ? body.data
    : (Array.isArray(body) ? body : []);

  // Map to lean format
  const agents = data.map((a) => ({
    slug: a && a.slug,
    name: a && a.name,
    description: a && a.description,
  category: a && a.category,
  }));

  // Client-side search filter
  let filtered = agents;
  if (q && q.trim()) {
    const query = q.toLowerCase();
    filtered = agents.filter((agent) => {
      const searchable = [
        agent.name,
        agent.slug,
        agent.description,
        agent.category
      ].join(' ').toLowerCase();
      return searchable.includes(query);
    });
  }

  // Pagination
  const total = filtered.length;
  const paginated = filtered.slice(offset, offset + limit);
  const hasMore = (offset + limit) < total;

  return {
    agents: paginated,
    count: paginated.length,
    total: total,
    limit: limit,
    offset: offset,
    hasMore: hasMore
  };
}
